# Exact verifier logic used for the 2,228-case MINSRC2 research recheck.
# Input files are expected to be generated by BYTES_MINSRC2_FRESH_CASE_GENERATOR_20261009_V1.py
# and by executing the candidate capsule to produce {"outs":[{"id":...,"out":...}, ...]}.
import json, math, sys
from fractions import Fraction
import sympy as sp

cases=json.load(open(sys.argv[1]))['cases']
outs={o['id']:o['out'] for o in json.load(open(sys.argv[2]))['outs']}
x=sp.Symbol('x')

def dec(z):
    t=z[0]
    if t=='I': return sp.Integer(z[1])
    if t=='Q': return sp.Rational(z[1],z[2])
    if t=='PI': return sp.pi
    if t=='S': return sp.Symbol(z[1])
    if t=='L': return [dec(v) for v in z[1]]
    if t=='E':
        name=z[1]; a=[dec(v) for v in z[2]]
        f={'Add':sp.Add,'Mul':sp.Mul,'Pow':sp.Pow,'exp':sp.exp,'cos':sp.cos,'sin':sp.sin,'log':sp.log}.get(name)
        if f is None: raise ValueError(('unknown tag',name))
        return f(*a)
    raise ValueError(z)

def poly(coeffs):
    n=len(coeffs)-1
    return sum(sp.Integer(c)*x**(n-i) for i,c in enumerate(coeffs))

def det_frac(mat):
    m=[list(map(Fraction,row)) for row in mat];n=len(m);det=Fraction(1)
    if n==0:return Fraction(1)
    for i in range(n):
        piv=next((r for r in range(i,n) if m[r][i]),None)
        if piv is None:return Fraction(0)
        if piv!=i:m[i],m[piv]=m[piv],m[i];det=-det
        p=m[i][i];det*=p
        for r in range(i+1,n):
            f=m[r][i]/p
            for c in range(i,n):m[r][c]-=f*m[i][c]
    return det

P=0
for c in cases:
    got=dec(outs[c['id']]); op=c['op']; ok=False
    if op=='rational_sum':
        ok=(got==sp.Rational(c['a_num'],c['a_den'])+sp.Rational(c['b_num'],c['b_den']))
    elif op=='factor':
        e=poly(c['coeffs']); ex=sp.factor(e)
        ok=(sp.expand(got-e)==0 and sp.factor(got)==ex)
    elif op=='coefficient':
        coeffs=c['coeffs'];deg=len(coeffs)-1;k=c['power']
        ok=(got==(coeffs[deg-k] if 0<=k<=deg else 0))
    elif op=='roots':
        e=poly(c['coeffs']); ex=sp.solve(e,x)
        ok=isinstance(got,list) and len(got)==len(ex) and all(any(sp.simplify(g-r)==0 for r in ex) for g in got)
    elif op=='differentiate':
        k=c['kind']
        if k=='xpowx': e=x**x
        elif k=='power': e=x**c['n']
        elif k=='exp_linear': e=sp.exp(c['a']*x)
        elif k=='sin_linear': e=sp.sin(c['a']*x)
        ok=(sp.simplify(got-sp.diff(e,x))==0)
    elif op=='integrate_sin_even':
        m=c['m']; ok=(sp.simplify(got-sp.Rational(math.comb(2*m,m),4**m)*sp.pi)==0)
    elif op=='determinant':
        ex=det_frac(c['matrix']); ok=(got==sp.Rational(ex.numerator,ex.denominator))
    elif op=='hilbert_determinant':
        n=c['n']; mat=[[Fraction(1,i+j-1) for j in range(1,n+1)] for i in range(1,n+1)]
        ex=det_frac(mat); ok=(got==sp.Rational(ex.numerator,ex.denominator))
    elif op=='binomial_square_sum':
        ok=(got==math.comb(2*c['n'],c['n']))
    elif op=='limit_sin_linear_over_x':
        ok=(got==c['a'])
    elif op=='linear2':
        a,b=c['A'][0];d,e=c['A'][1];u,v=c['b'];det=a*e-b*d
        ex=[Fraction(u*e-b*v,det),Fraction(a*v-u*d,det)]
        ok=isinstance(got,list) and len(got)==2 and all(got[i]==sp.Rational(ex[i].numerator,ex[i].denominator) for i in (0,1))
    elif op=='series_exp_sin_coeff':
        a,b,n=c['a'],c['b'],c['n'];ex=Fraction(0)
        for j in range((n-1)//2+1):
            q=2*j+1
            if q>n:break
            ex+=Fraction(((-1)**j)*(b**q)*(a**(n-q)),math.factorial(q)*math.factorial(n-q))
        ok=(got==sp.Rational(ex.numerator,ex.denominator))
    if not ok:
        raise SystemExit(f'FAIL id={c["id"]} op={op} got={got!r}')
    P+=1
print('PASS',P,'/',len(cases))
